import{_ as i,o as l,c as t,ae as e}from"./chunks/framework.Czhw_PXq.js";const r="/project-data.png",o="/project-data-arch.png",_=JSON.parse('{"title":"企业级数据分析平台","description":"","frontmatter":{"layout":"doc","title":"企业级数据分析平台"},"headers":[],"relativePath":"projects/data-analysis.md","filePath":"projects/data-analysis.md"}'),n={name:"projects/data-analysis.md"};function s(d,a,h,c,u,p){return l(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="企业级数据分析平台" tabindex="-1">企业级数据分析平台 <a class="header-anchor" href="#企业级数据分析平台" aria-label="Permalink to &quot;企业级数据分析平台&quot;">​</a></h1><h2 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h2><p>基于 Python + Streamlit 开发的可视化数据分析平台，支持多源数据接入、自动化分析、交互式图表展示，无需编程基础即可完成专业数据分析，帮助企业快速挖掘数据价值。</p><div style="text-align:center;margin:2rem 0;"><img src="'+r+'" alt="数据分析平台界面" style="width:80%;border-radius:14px;box-shadow:0 4px 16px rgba(0,0,0,0.1);"></div><h2 id="核心技术栈" tabindex="-1">核心技术栈 <a class="header-anchor" href="#核心技术栈" aria-label="Permalink to &quot;核心技术栈&quot;">​</a></h2><ul><li>后端：Python + FastAPI</li><li>数据分析：Pandas + NumPy + Scipy</li><li>可视化：Streamlit + Matplotlib + ECharts</li><li>数据存储：MySQL + MongoDB + MinIO</li><li>AI 分析：LangChain + 通义千问（自动生成分析结论）</li><li>数据接入：API + 爬虫 + 文件导入</li></ul><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ol><li>数据接入：支持 CSV/Excel/数据库/API 多源数据导入</li><li>数据清洗：自动去重、缺失值处理、异常值检测</li><li>可视化分析：折线图、柱状图、热力图等 20+ 图表</li><li>智能分析：AI 自动生成分析结论、趋势预测</li><li>报告导出：支持 PDF/Word/Excel 格式导出</li><li>定时任务：自动更新数据、生成日报/周报</li><li>权限管理：数据分级授权，保障数据安全</li></ol><h2 id="项目架构" tabindex="-1">项目架构 <a class="header-anchor" href="#项目架构" aria-label="Permalink to &quot;项目架构&quot;">​</a></h2><div style="text-align:center;margin:2rem 0;"><img src="'+o+'" alt="数据分析平台架构" style="width:85%;border-radius:14px;"></div><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>企业市场分析：用户增长、营销效果</li><li>电商运营分析：销售数据、库存周转</li><li>金融风险分析：交易数据、风险预警</li><li>教育数据统计：学生成绩、教学效果</li></ul><h2 id="项目亮点" tabindex="-1">项目亮点 <a class="header-anchor" href="#项目亮点" aria-label="Permalink to &quot;项目亮点&quot;">​</a></h2><ul><li>低代码/零代码操作，上手门槛低</li><li>交互式可视化，支持拖拽调整</li><li>AI 辅助分析，降低专业门槛</li><li>支持私有化部署，保障数据安全</li><li>可定制化开发，适配企业特殊需求</li></ul>',14)])])}const b=i(n,[["render",s]]);export{_ as __pageData,b as default};
